    /*
     * Add to the Lines
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	PurchaseOrder
     */
    public PurchaseOrder addToLines( UUID parentId, PurchaseOrderLine addTo ) {
	    LOGGER.info("handling AssignLinesToPurchaseOrderEvent - " );
	    
	    PurchaseOrder parentEntity = repository.findById(parentId).get();
	    PurchaseOrderLine child = registry.project( PurchaseOrderLine.class, addTo.getPurchaseOrderLineId());
	    
	    parentEntity.getLines().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Lines
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	PurchaseOrder
     */
	public PurchaseOrder removeFromLines( UUID parentId, PurchaseOrderLine removeFrom ) {
	    LOGGER.info("handling RemoveLinesFromPurchaseOrderEvent " );
	
	    PurchaseOrder parentEntity = repository.findById(parentId).get();
	    PurchaseOrderLine child = registry.project( PurchaseOrderLine.class, removeFrom.getPurchaseOrderLineId());
	    
	    parentEntity.getLines().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

